import React from "react";

const Login = () => {
  return (
    <div style={{ background: "#214a80", height: "100vh", display: "flex", alignItems: "center", justifyContent: "center" }}>
      <div className="login-dark" style={{ padding: "20px", borderRadius: "10px", background: "#fff", width: "300px", textAlign: "center" }}>
        <form>
          <h2>Login Form</h2>
          <div className="form-group">
            <input className="form-control" type="email" name="email" placeholder="Email" />
          </div>
          <div className="form-group">
            <input className="form-control" type="password" name="password" placeholder="Password" />
          </div>
          <div className="form-group">
            <button className="btn btn-primary btn-block">Log In</button>
          </div>
          <a className="forgot" href="#">Forgot your email or password?</a>
        </form>
      </div>
    </div>
  );
};

export default Login;
